sys_variable_value.value:
(function execute(inputs, outputs) {

    function toNum(v) {
        if (v === null || v === undefined) return 0;

        // Convert to string
        v = v.toString().trim();

        // REMOVE EVERYTHING except digits, minus, and decimal point
        // (commas, spaces, currency symbols, etc.)
        v = v.replace(/[^\d.-]/g, '');

        // Handle multiple commas or formatting weirdness
        if (v === '' || v === '-' || v === '.' || v === '-.') {
            return 0;
        }

        var n = parseFloat(v);
        return isNaN(n) ? 0 : n;
    }

    var a = toNum(inputs.valuea);
    var b = toNum(inputs.valueb);

    outputs.sum = a + b;

})(inputs, outputs);

